def fraction_to_repeating_decimal(numerator, denominator):
    if type(numerator) is not int or type(denominator) is not int:
        raise TypeError("numerator and denominator must be exact integers")
    if denominator == 0:
        raise ZeroDivisionError("denominator must be nonzero")
    if numerator == 0:
        return "0"

    negative = (numerator < 0) != (denominator < 0)
    numerator = abs(numerator)
    denominator = abs(denominator)
    integer_part, remainder = divmod(numerator, denominator)
    prefix = ("-" if negative else "") + str(integer_part)
    if remainder == 0:
        return prefix

    digits = []
    positions = {}
    while remainder and remainder not in positions:
        positions[remainder] = len(digits)
        digit, remainder = divmod(remainder * 10, denominator)
        digits.append(str(digit))

    if remainder == 0:
        return prefix + "." + "".join(digits)
    cycle_start = positions[remainder]
    return (prefix + "." + "".join(digits[:cycle_start]) + "(" +
            "".join(digits[cycle_start:]) + ")")

def is_isomorphic(s: str, t: str) -> bool:
    """
    Determines if two strings are isomorphic.

    Args:
    s (str): The first string.
    t (str): The second string.

    Returns:
    bool: True if the strings are isomorphic, False otherwise.
    """
    mapping_s_to_t = {}
    mapping_t_to_s = {}

    for char_s, char_t in zip(s, t):
        if char_s in mapping_s_to_t:
            if mapping_s_to_t[char_s] != char_t:
                return False
        else:
            mapping_s_to_t[char_s] = char_t

        if char_t in mapping_t_to_s:
            if mapping_t_to_s[char_t] != char_s:
                return False
        else:
            mapping_t_to_s[char_t] = char_s

    return True

def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def emirp_numbers(n):
    emirps = []
    for num in range(2, n + 1):
        if is_prime(num):
            reversed_num = int(str(num)[::-1])
            if num != reversed_num and is_prime(reversed_num):
                emirps.append(num)
    return sorted(emirps)

def final_position(commands):
    """
    Returns the final position of the robot after executing the commands.

    Args:
    commands (str): A string of commands where each command is one of 
                    'U', 'D', 'L', 'R' representing up, down, left, and right respectively.

    Returns:
    tuple: The final position of the robot as (x, y).
    """
    x, y = 0, 0
    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1
    return (x, y)

def min_operations(s1, s2):
    """
    Returns the minimum number of operations required to convert s1 into s2.
    The operations allowed are insertion, deletion, and replacement.
    """
    m, n = len(s1), len(s2)

    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j  # If s1 is empty, insert all characters of s2
            elif j == 0:
                dp[i][j] = i  # If s2 is empty, delete all characters of s1
            elif s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1]  # If characters match, no operation is needed
            else:
                dp[i][j] = 1 + min(dp[i-1][j],    # Deletion
                                   dp[i][j-1],    # Insertion
                                   dp[i-1][j-1])  # Replacement

    return dp[m][n]

def replaceCharacter(s, c):
    """
    Returns a new string where all occurrences of the character 'c' in string 's' 
    are replaced by the next character in the alphabet.
    """
    if not c.isalpha() or len(c) != 1 or c.lower() != c:
        raise ValueError("The character must be a single lowercase letter.")

    replacement = chr(((ord(c) - ord('a') + 1) % 26) + ord('a'))
    return s.replace(c, replacement)

def check_prime(n):
    """
    Determines if the given integer n is a prime number.

    Parameters:
    n (int): The integer to check for primality.

    Returns:
    bool: True if n is a prime number, False otherwise.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

from typing import List

def compute_lps(pattern: str) -> List[int]:
    M = len(pattern)
    lps = [0] * M
    length = 0
    i = 1

    while i < M:
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1

    return lps

def search_pattern(pattern: str, txt: str) -> List[int]:
    M = len(pattern)
    N = len(txt)

    lps = compute_lps(pattern)

    result = []
    i = 0
    j = 0

    while i < N:
        if pattern[j] == txt[i]:
            i += 1
            j += 1

        if j == M:
            return_start_index = i - j
            result.append(return_start_index)
            j = lps[j - 1]
        elif i < N and pattern[j] != txt[i]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return result

