    public static boolean isUndulating(long n) {
        String s = Long.toString(n);
        if (s.length() <= 2) {
            return false;
        }
        for (int i = 2; i < s.length(); i++) {
            if (s.charAt(i - 2) != s.charAt(i)) {
                return false;
            }
        }
        return true;
    }
}

