fn find_Rotations(str: String) -> isize {
    let n_chars = str.chars().count();
    let tmp = format!("{}{}", str, str);
    let tmp_chars: Vec<char> = tmp.chars().collect();
    for i in 1..=n_chars {
        let substring: String = tmp_chars[i..i + n_chars].iter().collect();
        if str == substring {
            return i as isize;
        }
    }
    n_chars as isize
}
